// Portfolio data — Marcello Ronchetti, fotografo di sport e motorsport.

export type Route =
  | 'cover'
  | 'gallery'
  | 'story'
  | 'videos'
  | 'contact'
  | 'experience'

// Semantic navigation target used by the views; App maps it onto router paths.
export type GoFn = (next: Route, ref?: string, tag?: string) => void

// URL slug for a category: lowercase, percent-encoded (matches the prerendered
// /gallery/<slug>/ paths generated by scripts/generate-seo-assets.mjs).
export const slugOf = (category: string) => encodeURIComponent(category.toLowerCase())

// Le quattro facce del rail 3D (SiteRail3d): navigare fra queste path NON usa
// la View Transition — la camera del rail È la transizione. Tutto il resto
// (storie, room, /experience, deep link da fuori) continua su vtNavigate.
export const RAIL_FACES: { path: string; label: string }[] = [
  { path: '/', label: 'Copertina' },
  { path: '/gallery', label: 'Galleria' },
  { path: '/videos', label: 'Video' },
  { path: '/contact', label: 'Contatti' },
]

export function isRailPath(pathname: string): boolean {
  return (
    pathname === '/' ||
    pathname === '/gallery' ||
    pathname.startsWith('/gallery/') ||
    pathname === '/videos' ||
    pathname === '/contact'
  )
}

